eventScripts.script:
#generate random faults
import random
lineCount = 7
tagPaths = ["[.]../Line %d/Plc/State" %line for line in range(1,lineCount+1) ]
tagPaths.extend("[.]../Line %d/Plc/ProductionCounter" %line for line in range(1,lineCount+1))


tagValues = system.tag.readBlocking(tagPaths)
for i in range(lineCount):

	if tagValues[i].value == 1:
		#if line is in running state, randomly generate a fault or idle
		if i == 0:  #line 1 is pretty faulty
			r = random.randint(1,15)
			if r == 6 :
				system.tag.writeAsync( "[.]../Line %d/Plc/State" %(i+1), 2)
			if r == 4 :
				system.tag.writeAsync( "[.]../Line %d/Plc/State" %(i+1), 0) 
		else:  #other lines not no much
			r = random.randint(1,50)
			if r in [11]:
				system.tag.writeAsync( "[.]../Line %d/Plc/State" %(i+1), 2)
			if r in [15]:
				system.tag.writeAsync( "[.]../Line %d/Plc/State" %(i+1), 0)


	elif tagValues[i].value != 1:
		#if line is arlready faulted, randonly set it running
		r = random.randint(1,5)
		if r == 5:
			system.tag.writeAsync( "[.]../Line %d/Plc/State" %(i+1), 1)
